CREATE TABLE author_assertions(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES authors(id),author_name TEXT NOT NULL,paper_id TEXT REFERENCES papers(id),paper_year INTEGER,kind TEXT NOT NULL,value TEXT NOT NULL,organization_id TEXT REFERENCES organizations(id),time_context TEXT NOT NULL,source_url TEXT NOT NULL,excerpt TEXT NOT NULL,page INTEGER,method TEXT NOT NULL,created REAL NOT NULL,status TEXT NOT NULL,supersedes_id TEXT REFERENCES author_assertions(id),corroborating_paper_id TEXT REFERENCES papers(id));
CREATE TABLE assertion_reviews(id TEXT PRIMARY KEY,assertion_id TEXT NOT NULL REFERENCES author_assertions(id),action TEXT NOT NULL,old_status TEXT NOT NULL,new_status TEXT NOT NULL,note TEXT NOT NULL,replacement_id TEXT REFERENCES author_assertions(id),created REAL NOT NULL);
CREATE TABLE enrichment_runs(id TEXT PRIMARY KEY,paper_id TEXT NOT NULL REFERENCES papers(id),method TEXT NOT NULL,status TEXT NOT NULL,started REAL NOT NULL,finished REAL,code TEXT,error TEXT,retryable INTEGER NOT NULL DEFAULT 0,assertions_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE enrichment_state(paper_id TEXT PRIMARY KEY REFERENCES papers(id),run_id TEXT REFERENCES enrichment_runs(id),status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,updated REAL NOT NULL,code TEXT,error TEXT,retryable INTEGER NOT NULL DEFAULT 0);
CREATE TABLE identity_proposals(id TEXT PRIMARY KEY,left_author_id TEXT NOT NULL REFERENCES authors(id),right_author_id TEXT NOT NULL REFERENCES authors(id),source_url TEXT NOT NULL,excerpt TEXT NOT NULL,assertion_ids TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL,created REAL NOT NULL);
CREATE TABLE identity_links(id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL UNIQUE REFERENCES identity_proposals(id),left_author_id TEXT NOT NULL REFERENCES authors(id),right_author_id TEXT NOT NULL REFERENCES authors(id),active INTEGER NOT NULL DEFAULT 1,created REAL NOT NULL);
CREATE TABLE identity_history(id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL REFERENCES identity_proposals(id),action TEXT NOT NULL,note TEXT NOT NULL,created REAL NOT NULL);
CREATE INDEX assertions_author ON author_assertions(author_id,status);
CREATE INDEX assertions_paper ON author_assertions(paper_id,status);
CREATE INDEX assertions_organization ON author_assertions(organization_id,kind,status);
